fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Since both arrays have the same length and arr2 contains no zeros,
    // we can safely zip and compute the remainder for each pair.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(a, b)| a % b)
        .collect()
}

