    #[test]
    fn test_basic() {
        let a = vec![10, 20, 30];
        let b = vec![3, 7, 11];
        // Expected remainders: [10 % 3 = 1, 20 % 7 = 6, 30 % 11 = 8]
        let expected = vec![1, 6, 8];
        assert_eq!(element_wise_module(&a, &b), expected);
    }

    #[test]
