        let b = vec![1, 2, 3, 2_u32.pow(31)];
        // 0%1=0, 1%2=1, 2%3=2, (2^31)%(2^31)=0
        let expected = vec![0, 1, 2, 0];
        assert_eq!(element_wise_module(&a, &b), expected);
